package com.skyreserve.model; import jakarta.persistence.*; import java.time.LocalDate; @Entity @Table(name="flights") public class Flight { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true) String code; String airline,origin,destination; LocalDate date; String time; double price; int rows,cols; public Flight(){} public Flight(String c,String a,String o,String d,LocalDate dt,String t,double p,int r,int cl){code=c;airline=a;origin=o;destination=d;date=dt;time=t;price=p;rows=r;cols=cl;} public Long getId(){return id;} public String getCode(){return code;} public String getAirline(){return airline;} public String getOrigin(){return origin;} public String getDestination(){return destination;} public LocalDate getDate(){return date;} public String getTime(){return time;} public double getPrice(){return price;} public int getRows(){return rows;} public int getCols(){return cols;} }
